    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files - this assumes filenames indicate order (e.g., timestamp or version prefix)
    sqlFiles.sort((a, b) => {
      // Simple string comparison - works if files are named with timestamps/versions
