          console.error(`Audit service error: ${res.statusCode} - ${data}`);
        }
        proceedWithMigrations();
      });
    });

    req.on('error', (error) => {
      console.error('Error sending audit log:', error);
      proceedWithMigrations();
    });

    req.write(auditData);
    req.end();

  } catch (error) {
    console.error('Error:', error);
    process.exit(1);
  }
}

