#!/usr/bin/env node

/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Migrations directory
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

async function main() {
  // Check if migrations directory exists
  try {
    const stats = fs.statSync(MIGRATIONS_DIR);
    if (!stats.isDirectory()) {
      console.error(`Error: ${MIGRATIONS_DIR} is not a directory`);
      process.exit(1);
    }
  } catch (err) {
    console.error(`Error: Migrations directory ${MIGRATIONS_DIR} does not exist`);
    process.exit(1);
  }

  // Read files from migrations directory
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them in ascending order
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Try to extract numeric prefix if exists
        const aNum = parseInt(a.match(/^\d+/)[0]);
        const bNum = parseInt(b.match(/^\d+/)[0]);

        if (!isNaN(aNum) && !isNaN(bNum)) {
          return aNum - bNum;
        }

        // Fallback to lex order
        return a.localeCompare(b);
      });

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found');
      return;
    }

    console.log('Migrations to apply:');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal migrations: ${sqlFiles.length}`);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }
}

// Execute main function
main().catch(err => {
  console.error('Unhandled error:', err);
  process.exit(1);
});

