#!/usr/bin/env node
/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs each filename it would apply in order.
 * Also reads DATABASE_URL from .env.test and logs connection.
 */

import fs from 'fs';
import path from 'path';
import dotenv from 'dotenv';

// Load environment variables from .env.test
dotenv.config({ path: '.env.test' });

const MIGRATIONS_DIR = path.join(process.cwd(), 'migrations');

function getMigrations() {
  try {
    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files.filter(file => file.endsWith('.sql'));
    sqlFiles.sort(); // Sort alphabetically to ensure correct order

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.warn(`Migrations directory not found at ${MIGRATIONS_DIR}. No migrations to apply.`);
      return [];
    }
    throw error;
  }
}

function main() {
  // Log connection message with DATABASE_URL (masking for security)
  const dbUrl = process.env.DATABASE_URL || 'NOT_SET';
  const maskedUrl = dbUrl.replace(/:.*@/, ':*****@');

  console.log(`✅ Connected to database: ${maskedUrl}`);

  // Get migration files
  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log('\nMigrations to apply (in order):');
  migrations.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\nMigration script completed.');
}

main().catch(error => {
  console.error('Error running migrations:', error);
  process.exit(1);
});

